// Lit games_details.csv et découpe en batches de 500
// pour éviter les timeouts Neo4j sur 668k lignes
const fs = require('fs');
const path = require('path');

const DATA_DIR  = process.env.NBA_DATA_DIR || '/data/nba';
const BATCH_SIZE = 500;

const content = fs.readFileSync(path.join(DATA_DIR, 'games_details.csv'), 'utf8');
const lines   = content.trim().split('\n');
const headers = lines[0].split(',').map(h => h.trim().replace(/"/g,''));

function parseMin(s) {
  if (!s || s === 'nan') return null;
  const p = s.split(':');
  if (p.length !== 2) return null;
  const t = parseInt(p[0]) * 60 + parseInt(p[1]);
  return (t >= 0 && t <= 3180) ? t : null;
}

function safe(v) {
  if (v === null || v === undefined || v === '' || v === 'nan' || v === 'NaN') return null;
  const n = parseFloat(v);
  return isNaN(n) ? null : n;
}

// Construire tous les records valides
const allRecords = [];
const seen = new Set();

for (let i = 1; i < lines.length; i++) {
  const vals = lines[i].split(',');
  if (vals.length < headers.length) continue;
  const row = {};
  headers.forEach((h, idx) => {
    const v = vals[idx] ? vals[idx].trim().replace(/"/g,'') : null;
    row[h] = (!v || v === 'nan' || v === 'NaN') ? null : v;
  });

  const gid = parseInt(row['GAME_ID']);
  const pid = parseInt(row['PLAYER_ID']);
  const tid = parseInt(row['TEAM_ID']);
  if (isNaN(gid) || isNaN(pid) || isNaN(tid)) continue;
  if (!row['MIN']) continue; // DNP — skip

  const key = `${pid}_${gid}`;
  if (seen.has(key)) continue;
  seen.add(key);

  const fgm  = safe(row['FGM']);
  const fga  = safe(row['FGA']);
  const fg3m = safe(row['FG3M']);
  const fg3a = safe(row['FG3A']);
  const ftm  = safe(row['FTM']);
  const fta  = safe(row['FTA']);
  const pts  = safe(row['PTS']);

  // Règles de validation
  if (fgm !== null && fga !== null && fgm > fga)   continue;
  if (fg3m!== null && fg3a!== null && fg3m > fg3a) continue;
  if (fg3a!== null && fga !== null && fg3a > fga)  continue;
  if (ftm !== null && fta !== null && ftm > fta)   continue;
  if (fgm !== null && fg3m !== null && ftm !== null && pts !== null) {
    const calc = (fgm - fg3m) * 2 + fg3m * 3 + ftm;
    if (Math.abs(calc - pts) > 1) continue;
  }

  allRecords.push({
    id:           key,
    joueur_id:    String(pid),
    match_id:     String(gid),
    equipe_id:    String(tid),
    position:     row['START_POSITION'] || '',
    min_secondes: parseMin(row['MIN']),
    fgm, fga, fg3m, fg3a, ftm, fta,
    oreb:         safe(row['OREB']),
    dreb:         safe(row['DREB']),
    reb:          safe(row['REB']),
    ast:          safe(row['AST']),
    stl:          safe(row['STL']),
    blk:          safe(row['BLK']),
    tov:          safe(row['TO']),
    pf:           safe(row['PF']),
    pts,
    plus_minus:   safe(row['PLUS_MINUS'])
  });
}

// Découper en batches
const batches = [];
for (let i = 0; i < allRecords.length; i += BATCH_SIZE) {
  batches.push({
    json: {
      batch_num:    Math.floor(i / BATCH_SIZE) + 1,
      total_batches: Math.ceil(allRecords.length / BATCH_SIZE),
      total_records: allRecords.length,
      rows:         allRecords.slice(i, i + BATCH_SIZE)
    }
  });
}

return batches;

const items = $input.all();
const total = items.reduce((s, i) => s + (i.json.nb || 0), 0);
console.log(`Performances insérées dans ce batch : ${total}`);
return items;
